SELECT COUNT(*) FILTER (WHERE currency = 'EUR')::numeric
       / NULLIF(COUNT(*) FILTER (WHERE currency = 'CZK'), 0) AS eur_to_czk_ratio
FROM public.customers;

SELECT COUNT(*) FILTER (WHERE country = 'CZE') - COUNT(*) FILTER (WHERE country = 'SVK') AS discount_station_difference
FROM public.gasstations
WHERE segment = 'Discount';

SELECT COUNT(*) FILTER (WHERE currency = 'CZK') - COUNT(*) FILTER (WHERE currency = 'EUR') AS more_smes_paying_in_czk
FROM public.customers
WHERE segment = 'SME';

SELECT 100.0 * COUNT(DISTINCT customerid) FILTER (WHERE consumption > 528.3) / NULLIF(COUNT(DISTINCT customerid), 0) AS percentage
FROM public.yearmonth
WHERE date = '201202';

SELECT MAX(CAST(consumption AS DOUBLE PRECISION)) AS highest_monthly_consumption
FROM public.yearmonth
WHERE SUBSTRING(date FROM 1 FOR 4) = '2012';
